          story: { zh: '老先生指著照片：「山上下來的樟腦、茶葉、木材，全部在這裡裝船，運去艋舺、大稻埕，再出口到國外。」小Q問：「一艘船能載多少？」老先生想了想：「阿祖的帳冊寫，一艘一趟大約 {30} 擔。」小Q轉向安安：「河運最盛的時候有 {250} 艘商船。全部一起出航，一趟能運幾擔？」',
                   en: 'The old man points at the photograph: “Camphor, tea and timber came down from the hills and were loaded here, bound for Bangka and Dadaocheng, and then abroad.” Little Q asks: “How much did one boat carry?” He considers: “Great-grandfather’s ledger says about {30} loads a trip.” Little Q turns to An-An: “At its height the river held {250} trading boats. If all sailed together, how many loads in one trip?”' },
          clueNote: { zh: '250 艘商船 × 每艘 30 擔＝一趟 7500 擔；貨物是山上下來的樟腦、茶、木材', en: '250 boats × 30 loads = 7,500 loads per trip; the cargo was camphor, tea and timber from the hills' },
