            reward: { zh: '📊 17000 車！江阿伯的手停在半空中：「一萬七千台卡車……」他看著自己店門口那條窄窄的老街，「這條街停得下嗎？」小Q輕輕地說：「所以它們不走這條街。它們從山裡出來，走另一條路。」',
                      en: '📊 17,000 truckloads! Uncle Jiang’s hand stops in mid-air: “Seventeen thousand lorries…” He looks out at the narrow old street before his shop. “Would they even fit?” Little Q says quietly: “Which is why they did not come down this street. They came out of the hills, by another road.”' },
