                  reward: { zh: '🔦 96 盞！老礦工終於開口了，聲音很啞：「一盞燈，一個人。下坑的時候一人拿一盞，上來要掛回去。」他停了很久：「每天收工，管燈的人會數燈。**少一盞，就代表有一個人還在下面。**」他沒有再說下去。安安也沒有再問。',
                            en: '🔦 96 lamps! At last the old miner speaks, his voice hoarse: “One lamp, one man. You took one going down and hung it back coming up.” He is quiet a long while. “At the end of every shift the lamp keeper counted them. **One missing meant a man was still below.**” He says no more. An-An does not ask.' },
